import { Effect } from "effect"

export const readCookie = Effect.fn("Cookies.readCookie")(
  function* (header: string | null, name: string) {
    if (header === null) {
      return undefined
    }

    const prefix = `${name}=`
    const entry = header
      .split(";")
      .map((part) => part.trim())
      .find((part) => part.startsWith(prefix))

    if (entry === undefined) {
      return undefined
    }

    const raw = entry.slice(prefix.length)

    return yield* Effect.try(() => decodeURIComponent(raw)).pipe(
      Effect.catchTags({
        UnknownError: () => Effect.succeed(raw)
      })
    )
  }
)

export const readSessionCookie = Effect.fn("Cookies.readSessionCookie")(
  function* (request: Request) {
    return yield* readCookie(request.headers.get("cookie"), "session")
  }
)
